// Automatically generated cover-arts base64 assets to bypass cross-origin/iframe cookie issues.

export const COVER_ARTS: Record<string, string> = {
  "/cover-arts/aarzoo.jpg": "data:image/jpeg;base64,",
  "/cover-arts/chapter1.jpg": "data:image/jpeg;base64,",
  "/cover-arts/chapter2.jpg": "data:image/jpeg;base64,",
  "/cover-arts/chapter3.jpg": "data:image/jpeg;base64,",
  "/cover-arts/chapter4.jpg": "data:image/jpeg;base64,",
  "/cover-arts/chapter5.jpg": "data:image/jpeg;base64,",
  "/cover-arts/kasoor.jpg": "data:image/jpeg;base64,",
  "/cover-arts/lost-within.jpg": "data:image/jpeg;base64,",
  "/cover-arts/noor.jpeg": "data:image/jpeg;base64,",
  "/cover-arts/mashup.jpg": "data:image/jpeg;base64,",
  "/cover-arts/logo.png": "data:image/png;base64,",
};

export function getCoverArt(path: string | undefined): string {
  if (!path) return "";
  const cleanPath = path.startsWith("/") ? path : "/" + path;
  return COVER_ARTS[cleanPath] || path;
}
